const paths = ["package.json", "release/local-signoff.json", "website/package.json"];
const rs = await Promise.allSettled(paths.map(path => tools.read_file({path})));
const observations = rs.map((r, i) => r.status === "fulfilled" ? {path:paths[i], value:r.value} : {path:paths[i], error:String(r.reason?.message ?? r.reason)});
return observations.map(o => {
  if (o.error) return {path:o.path, error:o.error};
  const v=o.value;
  if (v && typeof v === "object" && "content" in v) return {path:o.path, content:v.content};
  return {path:o.path, content: typeof v === "string" ? v : JSON.stringify(v)};
});

